  if (projectName2) lines.push(`- **${L.project}**\uFF1A${projectName2}`);
  if (agentName2) lines.push(`- **${L.agent}**\uFF1A${agentName2}`);
  if (modelName2) lines.push(`- **${L.model}**\uFF1A${modelName2}`);
