        if (h.concurrentMinutes > 0) {
          const conc = fill2.createDiv({ cls: "ad-review__rhythm-conc" });
          conc.style.height = `${Math.max(8, Math.min(100, Math.round(100 * h.concurrentMinutes / h.minutes)))}%`;
        }
